UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var car = GameObject.Find("GARAGE / PLAYER");
if (car == null) return "no car";
sb.AppendLine("car=" + car.name + " rootFwd=" + car.transform.forward + " rootPos=" + car.transform.position);
var body = car.transform.Find("BODY / hdSportsCar");
sb.AppendLine("bodyRoot null=" + (body == null));
if (body != null)
{
    sb.AppendLine("body localRot=" + body.localRotation.eulerAngles + " localFwd=" + body.forward);
    // Where are the wheels in the body root's local space?
    foreach (Transform t in body.GetComponentsInChildren<Transform>())
    {
        if (t.name == "wheel_fl" || t.name == "wheel_fr" || t.name == "wheel_rl" || t.name == "wheel_rr")
            sb.AppendLine("  " + t.name + " localPos=" + t.localPosition);
    }
}
// Where is the nose? Find the light kit and the wing.
var kit = car.transform.Find("AURORA light kit");
if (kit != null)
{
    foreach (Transform t in kit)
    {
        if (t.name.Contains("DRL")) sb.AppendLine("  DRL " + t.name + " localPos=" + t.localPosition);
        if (t.name.Contains("LED")) sb.AppendLine("  LED " + t.name + " localPos=" + t.localPosition);
    }
}
var aero = car.transform.Find("AURORA aero kit");
if (aero != null) sb.AppendLine("aero localPos=" + aero.localPosition);
// Ground truth: the steering wheel mesh sits at the front of the cabin.
var steer = car.GetComponentsInChildren<Transform>();
foreach (Transform t in steer) if (t.name.ToLower().Contains("steering")) sb.AppendLine("  steering localPos(body space)=" + (body != null ? body.InverseTransformPoint(t.position).ToString() : t.position.ToString()));
Debug.Log("PROBE2 " + sb.ToString().Replace("\r", "").Replace("\n", " | "));
return sb.ToString();
